    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    m = int(data[1 + n])
    q = data[2 + n:2 + n + m]
    pos = {}
    for j, w in enumerate(q):
        pos.setdefault(w, []).append(j)
    for w in pos:
        pos[w].reverse()
    dp = [-1] * m
    best = 10 ** 9
    bs = be = -1
    for i, w in enumerate(words):
        js = pos.get(w)
        if not js:
            continue
        for j in js:
            if j == 0:
                dp[0] = i
            elif dp[j - 1] >= 0:
                dp[j] = dp[j - 1]
            if j == m - 1 and dp[j] >= 0 and i - dp[j] < best:
                best = i - dp[j]
                bs, be = dp[j], i
    print(bs, be)

