data = sys.stdin.read().split()
n = int(data[0])
words = data[1:1 + n]
m = int(data[1 + n])
q = data[2 + n:2 + n + m]

def ok(s, e):
    j = 0
    for i in range(s, e + 1):
        if j < m and words[i] == q[j]:
            j += 1
    return j == m

ans = (-1, -1)
done = False
for length in range(0, n):
    for s in range(0, n - length):
        if ok(s, s + length):
            ans = (s, s + length)
            done = True
            break
    if done:
        break
print(ans[0], ans[1])

